head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");


//2010.06.25  전부보유리스트 조치_STF35500 변경에 따라 자전거래 항목 삭제 

scwin.vScrenID = "ULDSTF35503.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    if (parseInt(edt_START_DD.getValue(), '10') > parseInt(edt_END_DD.getValue(), '10')) {
        $c.win.alert("[시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return;
    }
    var url = "/ELWAllHoldAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listELWLPHoldingQuantity&inputMessageId=ELW_LP_ALL_HD_TASK_DD_GET_OUT";
    url += "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    url += "&SDATE=" + $c.stf.getObjectValue(edt_START_DD);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_END_DD);
    dts_ELW_HD_DTL.DataID = encodeURI(url);
    dts_ELW_HD_DTL.reset();
    $c.cm.ShowWin(grd_ELW_HD_DTL);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_ELW_HD_DTL_OnLoadError = function() {
    $c.stf.alert_error(dts_ELW_HD_DTL);
};
scwin.dts_ELW_HD_DTL_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt.setValue("총 " + dts_ELW_HD_DTL.getTotalRow() + "건");
    $c.cm.CloseWin(rowcount, grd_ELW_HD_DTL);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_START_DD_onclick = function() {
    popUpCalendar2(edt_START_DD);
};
scwin.img_END_DD_onclick = function() {
    popUpCalendar2(edt_END_DD);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var parentWin = $c.frame.path("../");
    txb_ISU_CD.setValue(parentWin.clickIsuCd);
    txb_ISU_NM.setValue(parentWin.clickIsuKorAbbrv);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_START_DD.setValue($c.ut.cGetMinusDate2(vCurDate, 30));
    edt_END_DD.setValue(vCurDate);
    scwin.fn_list_sync();
};
